// Closed outlines (sketch units) for a line of text: baseline starts at (x, y), cap height ~ h, rotated by angle (deg).
export function textPolys(t) {
  const s = (+t.h || 10) / 729, a = (+t.angle || 0) * Math.PI / 180, ca = Math.cos(a), sa = Math.sin(a), polys = [];
  let pen = 0; const str = String(t.str ?? '');
  for (const ch of str) {
    const g = GLYPHS[ch] || GLYPHS['?'];
    for (const c of g[1]) { const pts = []; for (let i = 0; i < c.length; i += 2) { const lx = (pen + c[i]) * s, ly = c[i + 1] * s; pts.push({ x: +t.x + lx * ca - ly * sa, y: +t.y + lx * sa + ly * ca }); } polys.push(pts); }
    pen += g[0] + (+t.spacing || 0) * 10;
  }
  return { polys, width: pen * s };
}
// Legacy-style closed profiles for every text item of a sketch (holes come from nesting).
export function textProfiles(sk, refs) {
  const out = [];
  for (const t of sk.texts || []) {
    const { polys } = textPolys(t);
    if (refs?.length) { const xs = polys.flat(); if (!xs.length) continue; const x0 = Math.min(...xs.map(p => p.x)), x1 = Math.max(...xs.map(p => p.x)), y0 = Math.min(...xs.map(p => p.y)), y1 = Math.max(...xs.map(p => p.y));
      if (!refs.some(r => r.text === t.id || (r.x >= x0 && r.x <= x1 && r.y >= y0 && r.y <= y1))) continue; }
    polys.forEach((pts, i) => out.push({ id: t.id + '#' + i, kind: 'poly', pts, text: t.id }));
  }
  return out;
}
